   public String visit(AssignmentStatement n, String argu) {
    if(debug){System.out.println("Visiting AssignmentStatement");}
      String _ret=null;
      String varName = n.f0.f0.toString();
      n.f1.accept(this, argu);
      String RHS = n.f2.accept(this, argu);
      // Map variable to TEMP; if it's a field, do HSTORE on this (TEMP 0)
      String helper = "";
      String lhsTemp = st.getTempForVariable(currClass, currMethod, varName);
      if (lhsTemp != null) {
         res += ("  MOVE " + lhsTemp + " " + RHS + "\n");
      } else {
         int off = st.getFieldOffset(currClass, varName);
         if (off >= 0) {
            res += ("  HSTORE TEMP 0 " + off + " " + RHS + "\n");
         } else {
            // fallback: treat as plain temp name
            res += ("  MOVE " + varName + " " + RHS + "\n");
         }
      }
      n.f3.accept(this, argu);
      return _ret;
   }

