   /**
    * f0 -> PrimaryExpression()
    * f1 -> "."
    * f2 -> Identifier()
    * f3 -> "("
    * f4 -> ( ExpressionList() )?
    * f5 -> ")"
    */
   public String visit(MessageSend n, String argu) {
       String objTemp = n.f0.accept(this, argu); // object (like TEMP 0)
     n.f1.accept(this, argu); // skip dot
     String methodName = n.f2.f0.tokenImage;
     n.f3.accept(this, argu); // skip '('
       ExpressionList exprList = null;
       if(n.f4.present()) exprList = (ExpressionList)n.f4.node;
     n.f5.accept(this, argu); // skip ')'

     // Determine class of the object (recorded at allocation time)
     String className = st.getClassForTemp(objTemp);
     if(className == null){
        className = currClass; // fallback
     }

     int methodOff = st.getMethodOffset(className, methodName);

     // Load vtable and method address
     String vtabTemp = newTemp();
     emit("  HLOAD " + vtabTemp + " " + objTemp + " 0");
     String methodAddr = newTemp();
     emit("  HLOAD " + methodAddr + " " + vtabTemp + " " + methodOff);

     // collect args
     List<String> args = new ArrayList<>();
     args.add(objTemp); // 'this' first
     if(exprList != null){
        args.addAll(collectArgs(exprList, argu));
     }

     // Build argument string with spaces
     StringBuilder argStr = new StringBuilder();
     for(int i=0;i<args.size();i++){
        if(i!=0) argStr.append(" ");
        argStr.append(args.get(i));
     }
     // Return inline CALL expression so PRINT can be "PRINT CALL ..."
     return "CALL " + methodAddr + "(" + argStr.toString() + ")";
   }

   // Helper to collect arguments recursively
   private List<String> collectArgs(ExpressionList n, String argu){
      List<String> args = new ArrayList<>();
      args.add(n.f0.accept(this, argu));
      if (n.f1 != null && n.f1.present()) {
         for (Enumeration<Node> e = n.f1.elements(); e.hasMoreElements(); ) {
            ExpressionRest er = (ExpressionRest) e.nextElement();
            args.add(er.f1.accept(this, argu));
         }
      }
      return args;
   }


   /**
    * f0 -> Expression()
    * f1 -> ( ExpressionRest() )*
    */
   public String visit(ExpressionList n, String argu) {
      String first = n.f0.accept(this, argu);
      StringBuilder sb = new StringBuilder();
      sb.append(first);
      if (n.f1 != null && n.f1.present()) {
         for (Enumeration<Node> e = n.f1.elements(); e.hasMoreElements(); ) {
            ExpressionRest er = (ExpressionRest) e.nextElement();
            String more = er.f1.accept(this, argu);
            sb.append(" ").append(more);
         }
      }
      return sb.toString();
   }

