   /**
    * f0 -> <IDENTIFIER>
    */
   public String visit(Identifier n, String argu) {
      String _ret=null;
      String id = n.f0.toString();
     String temp = st.getTempForVariable(currClass,currMethod,id);
     if(temp!=null){
        return temp;
     }
     // Field read: load from this + offset
     int off = st.getFieldOffset(currClass, id);
     if (off >= 0) {
        String t = newTemp();
        emit("  HLOAD " + t + " TEMP 0 " + off);
        return t;
     }
     return id;
   }

